INSERT INTO problems (problem_id, customer_id, category_id, neighborhood_id, address, title, description, contact_phone, budget, urgency, preferred_date, status, assigned_worker_id, created_at, updated_at) VALUES
(1, 44, 15, 1, 'Rruga Bujar Bishanaku, pallati 25', 'Riparime të vogla në shtëpi', 'Disa punë të vogla: dorezë dere e lirë, një raft që ka rënë dhe silikon në banjo. Materialet mund t''i blej vetë nëse më thoni çfarë duhet. Shtëpia është private me oborr.', '0681284001', NULL, 'low', NULL, 'completed', 25, '2025-11-17 09:52:40', '2025-11-18 18:13:22'),
(2, 74, 1, 24, NULL, 'Plasi tubi i ujit në oborr', 'Me të ftohtin e natës plasi tubi i ujit në oborr dhe rrjedh pa ndalim. E kam mbyllur ujin te sahati. Jam në katin e pestë, ka ashensor. Jam në katin e katërt, pallati nuk ka ashensor.', '0686113875', NULL, 'high', NULL, 'completed', 3, '2025-11-19 12:33:54', '2025-11-22 14:50:07'),
(3, 97, 12, 17, 'Rruga Hasan Riza Pasha, pallati 32', 'Kangjella hekuri për ballkon', 'Dua kangjella të reja hekuri për ballkonin, rreth 5 m të gjata, të lyera. Jam në mërgim, punën e ndjek motra ime që jeton aty.', '0674704247', 44000.0, 'normal', '2025-12-17', 'completed', 25, '2025-12-09 10:45:21', '2025-12-17 13:45:42'),
(4, 59, 15, 21, NULL, 'Riparime të vogla në shtëpi', 'Disa punë të vogla: dorezë dere e lirë, një raft që ka rënë dhe silikon në banjo. Shtëpia është private me oborr. Mund të vini pas orës 17:00, para jam në punë.', '0694316349', 5500.0, 'normal', '2025-12-16', 'completed', 3, '2025-12-10 17:05:40', '2025-12-16 21:11:27'),
(5, 32, 11, 13, NULL, 'Pllaka të thyera në kuzhinë', 'Në dyshemenë e kuzhinës janë thyer katër pllaka. Kam pllaka rezervë nga i njëjti model. Preferoj në mëngjes, para orës 12.', '0699004422', 6500.0, 'low', NULL, 'cancelled', NULL, '2025-12-15 16:25:23', '2025-12-23 00:36:23'),
(6, 90, 5, 3, 'Rruga Marin Barleti, pallati 34', 'Lagështi në murin e katit përdhe', 'Pas përmbytjes së dimrit muri i katit përdhe thith ujë, suvaja po bie. Duhet hequr suvaja dhe izoluar. Pagesa cash në fund të punës.', '0698296017', 17500.0, 'normal', '2025-12-23', 'completed', 21, '2025-12-16 14:02:20', '2026-01-04 15:49:13'),
(7, 80, 5, 7, 'Rruga At Gjergj Fishta, pallati 23', 'Riparim shkallësh në oborr', 'Shkallët prej betoni në hyrje të shtëpisë janë plasaritur dhe dy shkallë janë thyer. Jam në katin e tretë, ka ashensor. Preferoj në mëngjes, para orës 12.', '0678948746', NULL, 'normal', NULL, 'completed', 16, '2025-12-17 13:13:23', '2026-01-05 09:11:03'),
(8, 78, 2, 2, 'Rruga Mbretëresha Teutë, pallati 19', 'Montim interfoni në derë', 'Dua të montoj interfon me kamerë te dera e hyrjes së shtëpisë. Pajisjen e kam. Ju lutem më shkruani çmimin para se të vini. Jam në mërgim, punën e ndjek motra ime që jeton aty.', '0694461351', NULL, 'low', NULL, 'completed', 10, '2026-01-01 08:07:36', '2026-01-03 12:11:15'),
(9, 61, 14, 33, NULL, 'Transport mobiliesh brenda Shkodrës', 'Kam nevojë të transportoj një divan, një frigorifer dhe dy dollapë brenda qytetit, kati i tretë pa ashensor. Mund të vini pas orës 17:00, para jam në punë.', '0681120984', 11000.0, 'high', NULL, 'cancelled', NULL, '2026-01-05 13:53:08', '2026-01-13 13:53:08'),
(10, 49, 3, 19, NULL, 'Myk në mur nga lagështia', 'Pas dimrit doli myk i zi në murin e dhomës nga ana e veriut. Duhet pastruar, trajtuar dhe lyer me bojë kundër mykut. Jam në katin e tretë, pallati nuk ka ashensor. Mund të dërgoj edhe më shumë foto në mesazh.', '0691953918', 8000.0, 'normal', NULL, 'completed', 15, '2026-01-16 14:32:12', '2026-01-19 08:02:49'),
(11, 65, 11, 38, NULL, 'Ndërrim pllakash në banjo', 'Dua të heq pllakat e vjetra në banjo dhe të vendos të reja në mure e dysheme, rreth 22 m2 gjithsej. Ju lutem më shkruani çmimin para se të vini. Jam në katin e pestë, pallati nuk ka ashensor.', '0675213629', 52500.0, 'low', '2026-01-24', 'cancelled', NULL, '2026-01-19 10:57:52', '2026-01-23 01:15:52'),
(12, 74, 1, 24, 'Rruga Studenti, pallati 3', 'Presion shumë i ulët i ujit', 'Në kuzhinë e në banjo uji vjen shumë dobët, sidomos uji i ngrohtë. Fqinjët nuk e kanë këtë problem. Mund të dërgoj edhe më shumë foto në mesazh. Jam në katin e pestë, ka ashensor.', '0686113875', NULL, 'low', NULL, 'completed', 3, '2026-01-19 12:23:21', '2026-01-21 16:22:42'),
(13, 34, 4, 5, NULL, 'Dritarja prej druri fut ajër', 'Dritarja e vjetër prej druri në dhomën e ndenjes nuk mbyllet mirë dhe fut ajër e ujë kur bie shi. Mund të vini pas orës 17:00, para jam në punë. Mund të dërgoj edhe më shumë foto në mesazh.', '0695817625', NULL, 'normal', '2026-01-28', 'completed', 19, '2026-01-21 15:20:31', '2026-01-28 17:46:17'),
