(64, 35, 11, 1, 'Rruga Mbretëresha Teutë, pallati 20', 'Ndërrim pllakash në banjo', 'Dua të heq pllakat e vjetra në banjo dhe të vendos të reja në mure e dysheme, rreth 22 m2 gjithsej. Jam në mërgim, punën e ndjek motra ime që jeton aty. Preferoj në mëngjes, para orës 12.', '0670159450', 51500.0, 'normal', NULL, 'cancelled', NULL, '2026-06-23 15:57:41', '2026-06-24 15:57:41'),
(65, 95, 3, 3, 'Rruga 13 Dhjetori, pallati 19', 'Lyerje ballkoni dhe hekurave', 'Ballkoni ka bojën të rënë dhe hekurat kanë ndryshk. Duhet pastruar ndryshku dhe lyer. Kemi fëmijë të vegjël në shtëpi, prandaj sa më shpejt. Ju lutem më shkruani çmimin para se të vini.', '0694164975', 9000.0, 'low', NULL, 'completed', 15, '2026-06-25 07:03:34', '2026-06-27 10:58:25'),
(66, 50, 7, 13, 'Rruga Mbretëresha Teutë, pallati 24', 'Montim kondicioneri 12000 BTU', 'Kam blerë kondicioner 12000 BTU. Duhet montuar në dhomën e ndenjes, njësia e jashtme në ballkon. Jam në katin e dytë, pallati nuk ka ashensor. Pagesa cash në fund të punës.', '0676603304', 6500.0, 'normal', '2026-06-29', 'cancelled', NULL, '2026-06-27 11:28:21', '2026-06-28 11:28:21'),
(67, 90, 2, 3, NULL, 'Montim interfoni në derë', 'Dua të montoj interfon me kamerë te dera e hyrjes së shtëpisë. Pajisjen e kam. Jam në katin e pestë, ka ashensor.', '0698296017', NULL, 'low', '2026-07-08', 'completed', 8, '2026-06-27 15:31:32', '2026-07-08 17:57:24'),
