(114, 43, 2, 8, 'Rruga Ndre Mjeda, pallati 31', 'Nuk ka rrymë në gjysmën e shtëpisë', 'Prej mëngjesit nuk kemi rrymë në kuzhinë dhe në dy dhoma, ndërsa pjesa tjetër punon. Jam në katin e pestë, ka ashensor. Materialet mund t''i blej vetë nëse më thoni çfarë duhet.', '0676979780', NULL, 'emergency', NULL, 'completed', 10, '2026-09-19 19:08:48', '2026-09-20 13:23:16'),
(115, 50, 2, 13, 'Rruga Fushë Çela, pallati 8', 'Instalim elektrik për apartament të rikonstruktuar', 'Apartament 2+1 në rikonstruksion të plotë. Duhet instalim i ri elektrik, priza, çelësa dhe kuadri. Preferoj në mëngjes, para orës 12. Mund të vini pas orës 17:00, para jam në punë.', '0676603304', 73000.0, 'normal', '2026-10-03', 'completed', 7, '2026-09-20 07:14:52', '2026-09-22 14:00:00'),
(116, 59, 6, 21, 'Rruga Hasan Riza Pasha, pallati 24', 'Pastrim dhe riparim ulluqesh', 'Ulluqet janë bllokuar me gjethe dhe një pjesë ka rënë. Uji derdhet mbi mur. Preferoj në mëngjes, para orës 12. Mund të dërgoj edhe më shumë foto në mesazh.', '0694316349', 3800.0, 'normal', NULL, 'completed', 22, '2026-09-20 18:23:39', '2026-09-22 20:39:24'),
(117, 52, 1, 29, NULL, 'Ndërrim rubineti në banjo', 'Rubineti i lavamanit në banjo pikon gjithë kohën. Rubinetin e ri e kam blerë vetë, duhet vetëm montimi. Materialet mund t''i blej vetë nëse më thoni çfarë duhet. Jam në katin e tretë, pallati nuk ka ashensor.', '0697803704', 3000.0, 'low', NULL, 'cancelled', NULL, '2026-09-20 21:45:13', '2026-09-29 13:48:13'),
(118, 91, 1, 9, 'Rruga Ndre Mjeda, pallati 11', 'Bllokim i kanalit në banjo', 'Uji nuk ikën nga dushi dhe lavamani dhe vjen erë e keqe. Duhet zhbllokuar tubacioni. Kemi fëmijë të vegjël në shtëpi, prandaj sa më shpejt. Ju lutem më shkruani çmimin para se të vini.', '0692041263', NULL, 'high', NULL, 'completed', 3, '2026-09-21 10:07:19', '2026-09-23 21:58:09'),
(119, 83, 2, 8, 'Rruga Gjuhadol, pallati 24', 'Bie siguresa sa ndez stufën', 'Sa herë që ndez stufën elektrike bashkë me bojlerin bie siguresa. Duhet parë instalimi. Mund të dërgoj edhe më shumë foto në mesazh. Shtëpia është private me oborr.', '0681567959', NULL, 'high', NULL, 'assigned', 9, '2026-09-24 16:59:38', '2026-09-25 09:30:38'),
(120, 73, 13, 6, NULL, 'Pjatalarësja nxjerr ujë', 'Pjatalarësja nxjerr ujë poshtë derës gjatë larjes.', '0691635401', 3400.0, 'high', NULL, 'assigned', 5, '2026-09-27 14:33:11', '2026-09-28 05:49:11'),
(121, 94, 5, 2, 'Rruga Kolë Idromeno, pallati 4', 'Suvatim muri pas riparimit', 'Pas ndërrimit të tubave mbeti një pjesë muri pa suva rreth 6 m2. Duhet suvatuar dhe rregulluar. Ju lutem më shkruani çmimin para se të vini.', '0698181378', NULL, 'low', '2026-10-09', 'in_progress', 16, '2026-09-27 15:37:36', '2026-09-29 13:35:36'),
(122, 44, 1, 1, 'Rruga Studenti, pallati 12', 'Rrjedh uji poshtë lavamanit të kuzhinës', 'Prej dy ditësh pikon uji nga tubi poshtë lavamanit dhe dollapi u lag krejt. Mendoj se duhet ndërruar sifoni. Jam në katin e dytë, ka ashensor.', '0681284001', 2800.0, 'high', NULL, 'assigned', 4, '2026-09-28 16:51:27', '2026-09-29 11:14:27'),
(123, 47, 2, 21, NULL, 'Montim llambash në tavan', 'Duhen montuar pesë llamba tavani në apartament. Kabllot janë, llambat i kam blerë. Jam në katin e dytë, ka ashensor. Preferoj në mëngjes, para orës 12.', '0696780736', 3400.0, 'low', '2026-10-01', 'assigned', 11, '2026-09-30 19:24:43', '2026-10-01 08:59:43'),
(124, 83, 4, 8, NULL, 'Garderobë me masë', 'Dua një garderobë me masë 2.4 m të gjatë deri në tavan, me dyer rrëshqitëse. Kemi fëmijë të vegjël në shtëpi, prandaj sa më shpejt.', '0681567959', 80000.0, 'low', '2026-10-09', 'in_progress', 18, '2026-10-01 09:05:44', '2026-10-03 18:50:44'),
(125, 100, 6, 5, 'Rruga Ded Gjo Luli, pallati 31', 'Pastrim dhe riparim ulluqesh', 'Ulluqet janë bllokuar me gjethe dhe një pjesë ka rënë. Uji derdhet mbi mur. Jam në katin e dytë, pallati nuk ka ashensor. Preferoj në mëngjes, para orës 12.', '0687865893', NULL, 'low', NULL, 'in_progress', 22, '2026-10-01 22:33:16', '2026-10-03 19:54:16'),
(126, 89, 2, 29, NULL, 'Ndërrim kuadri elektrik', 'Kuadri elektrik është i vjetër, me siguresa me tel. Dua kuadër të ri me automatë dhe salvavitë. Pagesa cash në fund të punës. Jam në katin e pestë, pallati nuk ka ashensor.', '0690465873', NULL, 'low', '2026-10-10', 'in_progress', 7, '2026-10-02 14:05:14', '2026-10-03 12:57:14'),
(127, 54, 15, 19, 'Rruga Studenti, pallati 39', 'Riparime të vogla në shtëpi', 'Disa punë të vogla: dorezë dere e lirë, një raft që ka rënë dhe silikon në banjo. Materialet mund t''i blej vetë nëse më thoni çfarë duhet. Shtëpia është private me oborr.', '0693708538', 2200.0, 'low', NULL, 'in_progress', 31, '2026-10-02 18:02:37', '2026-10-04 13:35:37'),
(128, 49, 2, 19, 'Rruga Kiras, pallati 4', 'Ndërrim kuadri elektrik', 'Kuadri elektrik është i vjetër, me siguresa me tel. Dua kuadër të ri me automatë dhe salvavitë. Kemi fëmijë të vegjël në shtëpi, prandaj sa më shpejt. Ju lutem më shkruani çmimin para se të vini.', '0691953918', 12000.0, 'normal', NULL, 'assigned', 11, '2026-10-02 19:54:31', '2026-10-03 14:33:31'),
(129, 83, 3, 8, 'Rruga Vaso Pasha, pallati 28', 'Myk në mur nga lagështia', 'Pas dimrit doli myk i zi në murin e dhomës nga ana e veriut. Duhet pastruar, trajtuar dhe lyer me bojë kundër mykut. Jam në katin e dytë, ka ashensor. Mund të dërgoj edhe më shumë foto në mesazh.', '0681567959', 8500.0, 'normal', NULL, 'assigned', 16, '2026-10-03 22:33:09', '2026-10-04 07:06:09'),
(130, 93, 13, 4, NULL, 'Lavatriçja nuk shtrydh', 'Lavatriçja mbush dhe shkarkon ujin, por kazani nuk rrotullohet në shtrydhje. Shtëpia është private me oborr. Ju lutem më shkruani çmimin para se të vini.', '0670591483', NULL, 'high', NULL, 'in_progress', 5, '2026-10-04 10:04:08', '2026-10-05 20:47:08'),
(131, 35, 13, 7, 'Rruga Ded Gjo Luli, pallati 14', 'Furra elektrike nuk ndizet', 'Furra elektrike nuk ngroh më, sipër pjatat punojnë normalisht. Kemi fëmijë të vegjël në shtëpi, prandaj sa më shpejt.', '0670159450', 3700.0, 'normal', '2026-10-09', 'open', NULL, '2026-10-04 10:13:07', '2026-10-04 13:50:07'),
(132, 76, 14, 7, 'Rruga Kolë Idromeno, pallati 14', 'Lëvizje apartamenti', 'Po ndërrojmë apartament brenda Shkodrës. Duhet ngarkim, transport dhe shkarkim i gjithë shtëpisë 2+1. Mund të dërgoj edhe më shumë foto në mesazh. Jam në katin e pestë, ka ashensor.', '0677707751', NULL, 'low', NULL, 'open', NULL, '2026-10-04 19:48:18', '2026-10-04 19:48:18'),
(133, 74, 13, 24, NULL, 'Furra elektrike nuk ndizet', 'Furra elektrike nuk ngroh më, sipër pjatat punojnë normalisht. Kemi fëmijë të vegjël në shtëpi, prandaj sa më shpejt. Preferoj në mëngjes, para orës 12.', '0686113875', 4800.0, 'normal', '2026-10-08', 'open', NULL, '2026-10-07 10:54:29', '2026-10-07 12:40:29'),
(134, 74, 2, 24, 'Rruga Ndre Mjeda, pallati 9', 'Montim interfoni në derë', 'Dua të montoj interfon me kamerë te dera e hyrjes së shtëpisë. Pajisjen e kam. Mund të vini pas orës 17:00, para jam në punë. Shtëpia është private me oborr.', '0686113875', 3600.0, 'normal', NULL, 'open', NULL, '2026-10-07 11:25:53', '2026-10-07 11:25:53'),
(135, 59, 9, 21, 'Rruga At Gjergj Fishta, pallati 33', 'Pastrim xhamash dhe perdesh', 'Duhet larë xhamat e të gjitha dritareve dhe hequr e larë perdet në një shtëpi dykatëshe. Jam në mërgim, punën e ndjek motra ime që jeton aty. Jam në katin e tretë, pallati nuk ka ashensor.', '0694316349', 6500.0, 'low', '2026-10-21', 'open', NULL, '2026-10-07 13:51:24', '2026-10-07 13:51:24'),
(136, 52, 4, 29, NULL, 'Garderobë me masë', 'Dua një garderobë me masë 2.4 m të gjatë deri në tavan, me dyer rrëshqitëse. Jam në mërgim, punën e ndjek motra ime që jeton aty. Mund të vini pas orës 17:00, para jam në punë.', '0697803704', 81000.0, 'normal', NULL, 'open', NULL, '2026-10-09 18:02:56', '2026-10-10 02:41:56'),
(137, 87, 3, 6, 'Rruga Marin Barleti, pallati 24', 'Lyerje tavani në kuzhinë', 'Tavani i kuzhinës është nxirë nga avulli e tymi. Duhet lyer me bojë që lahet. Jam në katin e pestë, pallati nuk ka ashensor. Mund të dërgoj edhe më shumë foto në mesazh.', '0698719889', 6000.0, 'low', NULL, 'open', NULL, '2026-10-11 09:46:19', '2026-10-12 12:59:19'),
(138, 46, 1, 18, NULL, 'Montim bojleri të ri 80 litra', 'Kam blerë bojler të ri 80 litra. Duhet hequr i vjetri dhe montuar i riu në banjo, lidhjet janë aty. Preferoj në mëngjes, para orës 12.', '0686073927', 4600.0, 'low', NULL, 'open', NULL, '2026-10-13 15:30:29', '2026-10-13 15:30:29'),
(139, 83, 12, 8, 'Rruga Mbretëresha Teutë, pallati 30', 'Saldim strehe metalike', 'Streha metalike mbi derën e oborrit u shkëput nga era. Duhet saldim dhe përforcim. Mund të vini pas orës 17:00, para jam në punë. Jam në katin e dytë, pallati nuk ka ashensor.', '0681567959', NULL, 'high', NULL, 'open', NULL, '2026-10-14 16:15:46', '2026-10-14 18:10:46'),
(140, 80, 4, 7, 'Bulevardi Skënderbeu, pallati 5', 'Dritarja prej druri fut ajër', 'Dritarja e vjetër prej druri në dhomën e ndenjes nuk mbyllet mirë dhe fut ajër e ujë kur bie shi. Jam në katin e dytë, pallati nuk ka ashensor. Kemi fëmijë të vegjël në shtëpi, prandaj sa më shpejt.', '0678948746', 3600.0, 'low', '2026-10-26', 'open', NULL, '2026-10-14 17:01:11', '2026-10-15 00:56:11'),
(141, 97, 2, 17, 'Rruga At Gjergj Fishta, pallati 10', 'Montim interfoni në derë', 'Dua të montoj interfon me kamerë te dera e hyrjes së shtëpisë. Pajisjen e kam. Jam në katin e katërt, ka ashensor. Ju lutem më shkruani çmimin para se të vini.', '0674704247', 4500.0, 'normal', '2026-10-26', 'open', NULL, '2026-10-15 09:22:55', '2026-10-15 09:22:55'),
(142, 97, 7, 17, 'Rruga Kolë Idromeno, pallati 31', 'Kondicioneri nuk ngroh në dimër', 'Kondicioneri në modalitetin e ngrohjes nxjerr ajër të ftohtë dhe njësia e jashtme ngrin. Materialet mund t''i blej vetë nëse më thoni çfarë duhet. Ju lutem më shkruani çmimin para se të vini.', '0674704247', NULL, 'high', NULL, 'open', NULL, '2026-10-15 17:38:42', '2026-10-15 18:54:42'),
(143, 88, 10, 2, 'Rruga Ded Gjo Luli, pallati 16', 'Mbeta jashtë derës', 'Më mbeti çelësi brenda dhe dera u mbyll. Kam nevojë ta hap sa më shpejt pa e dëmtuar. Pagesa cash në fund të punës. Mund të vini pas orës 17:00, para jam në punë.', '0683111196', 5000.0, 'high', NULL, 'open', NULL, '2026-10-16 10:20:26', '2026-10-16 11:09:26'),
(144, 46, 9, 18, 'Rruga At Gjergj Fishta, pallati 1', 'Pastrim i thellë apartamenti', 'Apartament 2+1 rreth 80 m2. Pastrim i thellë: kuzhina, banjo, dritaret dhe dyshemetë. Jam në katin e katërt, ka ashensor. Mund të vini pas orës 17:00, para jam në punë.', '0686073927', NULL, 'low', NULL, 'open', NULL, '2026-10-17 12:32:37', '2026-10-17 16:59:37'),
(145, 46, 10, 18, NULL, 'Bravë sigurie në derë të blinduar', 'Dua të montoj bravë sigurie më të mirë në derën e blinduar të apartamentit. Jam në katin e dytë, ka ashensor. Mund të vini pas orës 17:00, para jam në punë.', '0686073927', 4400.0, 'low', '2026-11-06', 'open', NULL, '2026-10-24 14:07:00', '2026-10-24 15:32:00'),
(146, 80, 6, 7, NULL, 'Pikon çatia kur bie shi', 'Sa herë që bie shi i fortë pikon uji nga tavani i katit të fundit. Çatia është me tjegulla. Shtëpia është private me oborr. Jam në katin e katërt, pallati nuk ka ashensor.', '0678948746', 9500.0, 'high', NULL, 'open', NULL, '2026-10-26 21:15:36', '2026-10-27 01:03:36'),
(147, 98, 13, 19, 'Rruga Qemal Draçini, pallati 38', 'Lavatriçja nuk shtrydh', 'Lavatriçja mbush dhe shkarkon ujin, por kazani nuk rrotullohet në shtrydhje. Shtëpia është private me oborr. Jam në katin e katërt, pallati nuk ka ashensor.', '0686175442', NULL, 'normal', NULL, 'open', NULL, '2026-10-28 12:51:09', '2026-10-28 12:51:09'),
(148, 80, 15, 7, NULL, 'Riparime të vogla në shtëpi', 'Disa punë të vogla: dorezë dere e lirë, një raft që ka rënë dhe silikon në banjo. Mund të dërgoj edhe më shumë foto në mesazh.', '0678948746', 3700.0, 'low', NULL, 'open', NULL, '2026-10-28 13:26:37', '2026-10-28 13:26:37'),
(149, 3, 1, 3, 'Rruga Kiras, pallati 40', 'Instalim hidraulik për banjo të re', 'Po rikonstruktojmë banjon nga e para. Duhet bërë i gjithë instalimi i ujit të ftohtë e të ngrohtë dhe shkarkimet. Pagesa cash në fund të punës. Mund të dërgoj edhe më shumë foto në mesazh.', '0695188447', 41500.0, 'low', '2026-10-29', 'open', NULL, '2026-10-28 14:28:28', '2026-10-28 17:59:28'),
(150, 90, 9, 3, NULL, 'Pastrim i thellë apartamenti', 'Apartament 2+1 rreth 80 m2. Pastrim i thellë: kuzhina, banjo, dritaret dhe dyshemetë. Mund të vini pas orës 17:00, para jam në punë. Materialet mund t''i blej vetë nëse më thoni çfarë duhet.', '0698296017', NULL, 'low', '2026-11-12', 'open', NULL, '2026-11-01 16:38:50', '2026-11-01 16:38:50');
