INSERT INTO reviews (review_id, problem_id, worker_id, customer_id, rating, review_text, created_at) VALUES
(1, 1, 25, 44, 5, 'Shumë i kënaqur. Saktë në orar, nuk na la të prisnim. U përgjigj brenda një ore. Ju faleminderit për punën.', '2025-11-18 18:56:22');
INSERT INTO reviews (review_id, problem_id, worker_id, customer_id, rating, review_text, created_at) VALUES
(2, 2, 3, 74, 5, 'Shumë mirë! Erdhi po atë ditë që shkrova. Gjithçka funksionon perfekt. E rekomandoj!', '2025-11-25 00:52:07');
INSERT INTO reviews (review_id, problem_id, worker_id, customer_id, rating, review_text, created_at) VALUES
(3, 4, 3, 59, 5, 'Shumë i kënaqur. Na shpjegoi qartë çfarë ishte problemi. Gjithçka funksionon perfekt. Mori aq sa tha në ofertë, asnjë lek më shumë. E rekomandoj!', '2025-12-19 09:15:27');
INSERT INTO reviews (review_id, problem_id, worker_id, customer_id, rating, review_text, created_at) VALUES
(4, 3, 25, 97, 1, 'Zhgënjim. Shumë i sjellshëm dhe i qetë. Çmimi ishte i kripur. Saktë në orar, nuk na la të prisnim. Nuk e thërras më.', '2025-12-19 18:59:42');
INSERT INTO reviews (review_id, problem_id, worker_id, customer_id, rating, review_text, created_at) VALUES
(5, 8, 10, 78, 5, 'Shumë mirë! E zgjidhi problemin që herën e parë. Çmim i arsyeshëm për punën që bëri. Ju faleminderit për punën.', '2026-01-03 22:23:15');
INSERT INTO reviews (review_id, problem_id, worker_id, customer_id, rating, review_text, created_at) VALUES
(6, 6, 21, 90, 5, 'Përvojë e mirë. U përgjigj brenda një ore. Faleminderit!', '2026-01-04 20:28:13');
INSERT INTO reviews (review_id, problem_id, worker_id, customer_id, rating, review_text, created_at) VALUES
(7, 7, 16, 80, 2, 'Shumë shtrenjtë për një punë kaq të vogël. Mezi e kapa në telefon.', '2026-01-08 04:47:03');
INSERT INTO reviews (review_id, problem_id, worker_id, customer_id, rating, review_text, created_at) VALUES
(8, 10, 15, 49, 5, 'Çmim i arsyeshëm për punën që bëri. Faleminderit!', '2026-01-21 12:46:49');
INSERT INTO reviews (review_id, problem_id, worker_id, customer_id, rating, review_text, created_at) VALUES
(9, 12, 3, 74, 5, 'Erdhi në kohë, siç kishte thënë. Ktheu përgjigje menjëherë në mesazh. Do e thërras prapë.', '2026-01-24 14:52:42');
INSERT INTO reviews (review_id, problem_id, worker_id, customer_id, rating, review_text, created_at) VALUES
